from lesson_authoring import entry as E
B=[['拉丁 contra','在对面、相反、反对']]
C=B+[['英语 contra- + conception 的后部 → contraception','针对受孕采取预防措施 → 避孕']]
W=[
E('contraception','英 /ˌkɒntrəˈsepʃən/；美 /ˌkɑːntrəˈsepʃən/','避孕','采取措施，目的是避免怀孕。','现代造词，用 contra- 反对、阻止 + conception 的后部；conception 在这里取受孕义，不是想法或构思义。',C,'contraception 通常作为不可数名词，谈避孕这件事或方法总称。它说的是预防怀孕，不是终止已经存在的妊娠；读科普时把这个动作方向先分清，比把长单词硬译成几个词根有用。','methods of contraception；access to contraception；information about contraception。','contraception 是避孕的总称，a contraceptive 可以是一种避孕药具；abortion 指终止妊娠，是不同概念。',('The leaflet explains several methods of contraception.','这份宣传册介绍了几种避孕方法。'),('The class discussed how to find reliable information about contraception.','课堂讨论了如何找到可靠的避孕信息。'),sources=['https://www.etymonline.com/word/contraception','https://en.wiktionary.org/wiki/contraception']),
E('contraceptive','英 /ˌkɒntrəˈseptɪv/；美 /ˌkɑːntrəˈseptɪv/','避孕的；避孕药具','用于避免怀孕的；也可直接指具有这种用途的药物或器具。','可按 contraception 的 contracept- 词干 + -ive 理解；也有 contra- + conceptive 的构词分析，重点都是阻止受孕。',C+[['英语 contracept- + -ive → contraceptive','与避孕有关的；避孕用品']],'contraceptive methods 中它是形容词，修饰方法；a contraceptive 或 contraceptives 中它是名词，指避孕用品。中文都容易翻成“避孕”，但英语句子里一个要接名词，一个自己就能当名词。','a contraceptive method；contraceptive pills；contraceptive use；a range of contraceptives。','contraception 通常不可数，contraceptive 作名词可以数。词义只说明用途，不表示所有方法的效果和适用情形相同。',('The article compares different contraceptive methods.','这篇文章比较了不同的避孕方法。'),('The clinic provides information about contraceptives.','这家诊所提供避孕药具的相关信息。'),sources=['https://www.etymonline.com/word/contraceptive','https://en.wiktionary.org/wiki/contraceptive']),
E('contraband','英 /ˈkɒntrəbænd/；美 /ˈkɑːntrəbænd/','违禁品；走私货','规则明明不准带，这批东西却被带进来、运出去或持有。','最终接意大利语 contrabbando：contra 违反 + bando 命令、禁令；英语借入路线涉及法语 contrebande，也有西班牙语路径分析。',B+[['意大利 contra + bando → contrabbando；法语／西班牙语相关形式','违反禁令的交易、走私'],['英语 contraband','走私货；被禁止带入或持有的物品']],'机场、监狱或海关语境里的 contraband 都强调物品违反相应规则。东西本身未必处处违法，同一样物品在某个场所可能被禁止。它常作不可数名词，也可作定语，如 contraband goods。','seize contraband；smuggle contraband；contraband goods；search for contraband。','contraband 是违禁物或走私货，counterfeit 是假冒品；真货也可能因运输或持有方式违规而成为 contraband。',('Officers found contraband hidden inside the shipment.','执法人员在这批货物中发现了藏匿的违禁品。'),('Visitors were searched for contraband before entering.','访客进入前接受了违禁品检查。'),sources=['https://www.etymonline.com/word/contraband','https://en.wiktionary.org/wiki/contraband'])]
